Bitmask DP: the operation index is determined by how many pairs have already been removed (popcount/2 + 1). Always pair the lowest unused element to avoid redundant states.

```python
from typing import List
from math import gcd
from functools import lru_cache

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        m = len(nums)
        g = [[0] * m for _ in range(m)]
        for i in range(m):
            for j in range(i + 1, m):
                g[i][j] = gcd(nums[i], nums[j])
        full = (1 << m) - 1

        @lru_cache(maxsize=None)
        def dp(mask: int) -> int:
            if mask == full:
                return 0
            op = (bin(mask).count("1") >> 1) + 1
            # lowest unused index
            i = 0
            while mask >> i & 1:
                i += 1
            best = 0
            for j in range(i + 1, m):
                if not (mask >> j) & 1:
                    val = op * g[i][j] + dp(mask | (1 << i) | (1 << j))
                    if val > best:
                        best = val
            return best

        return dp(0)
```

