import math
import sys

class Solution:
    def abbreviateProduct(self, left: int, right: int) -> str:
        if hasattr(sys, "set_int_max_str_digits"):
            try:
                sys.set_int_max_str_digits(0)
            except Exception:
                pass
        # Count trailing zeros via factors of 2 and 5
        c2 = 0
        c5 = 0
        for i in range(left, right + 1):
            x = i
            while x % 2 == 0:
                x //= 2
                c2 += 1
            while x % 5 == 0:
                x //= 5
                c5 += 1
        C = min(c2, c5)
        prod = math.prod(range(left, right + 1))
        prod //= 10 ** C
        try:
            s = str(prod)
        except ValueError:
            # Fallback: compute prefix via logs and suffix via modular arithmetic
            suf = prod % 100000
            logsum = 0.0
            for i in range(left, right + 1):
                logsum += math.log10(i)
            logsum -= C
            frac = logsum - math.floor(logsum)
            pre = int(10 ** (frac + 4))
            return str(pre) + "..." + str(suf).zfill(5) + "e" + str(C)
        if len(s) > 10:
            return s[:5] + "..." + s[-5:] + "e" + str(C)
        return s + "e" + str(C)
