from typing import List

class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        digits = s[1:-1]

        def options(t: str) -> List[str]:
            res = []
            n = len(t)
            if n == 0:
                return res
            # integer form
            if n == 1 or t[0] != '0':
                res.append(t)
            # decimal forms
            for i in range(1, n):
                left, right = t[:i], t[i:]
                if (len(left) > 1 and left[0] == '0') or right[-1] == '0':
                    continue
                res.append(left + '.' + right)
            return res

        ans = []
        for i in range(1, len(digits)):
            for a in options(digits[:i]):
                for b in options(digits[i:]):
                    ans.append(f"({a}, {b})")
        return ans
