Classic reverse union-find approach: remove all hits first, union remaining bricks with a virtual roof node, then add hits back in reverse order and measure the growth of the roof component.

```python
from typing import List

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        g = [row[:] for row in grid]
        for r, c in hits:
            g[r][c] -= 1  # becomes 0 if brick existed, -1 if empty

        roof = m * n
        parent = list(range(m * n + 1))
        size = [1] * (m * n + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        def idx(r, c):
            return r * n + c

        for r in range(m):
            for c in range(n):
                if g[r][c] == 1:
                    if r == 0:
                        union(idx(r, c), roof)
                    if r > 0 and g[r - 1][c] == 1:
                        union(idx(r, c), idx(r - 1, c))
                    if c > 0 and g[r][c - 1] == 1:
                        union(idx(r, c), idx(r, c - 1))

        res = [0] * len(hits)
        dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
        for i in range(len(hits) - 1, -1, -1):
            r, c = hits[i]
            if g[r][c] == -1:
                g[r][c] = 0
                continue
            before = size[find(roof)]
            g[r][c] = 1
            if r == 0:
                union(idx(r, c), roof)
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and g[nr][nc] == 1:
                    union(idx(r, c), idx(nr, nc))
            after = size[find(roof)]
            res[i] = max(0, after - before - 1)
        return res
```

