class Solution:
    def clumsy(self, n: int) -> int:
        result = 0
        sign = 1
        i = n
        first = True
        while i > 0:
            # compute group i * (i-1) / (i-2)
            if i >= 3:
                group = i * (i - 1) // (i - 2)
            elif i == 2:
                group = i * (i - 1)
            else:
                group = i
            if first:
                result += group
                first = False
            else:
                result -= group
            i -= 3
            if i > 0:
                result += i
                i -= 1
        return result
```

