from typing import List

class Solution:
    def largestMagicSquare(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        # row prefix sums: rp[i][j] = sum of grid[i][0..j-1]
        rp = [[0] * (n + 1) for _ in range(m)]
        for i in range(m):
            for j in range(n):
                rp[i][j + 1] = rp[i][j] + grid[i][j]
        # column prefix sums: cp[j][i] = sum of grid[0..i-1][j]
        cp = [[0] * (m + 1) for _ in range(n)]
        for j in range(n):
            for i in range(m):
                cp[j][i + 1] = cp[j][i] + grid[i][j]

        def check(r, c, k):
            target = rp[r][c + k] - rp[r][c]
            for i in range(r, r + k):
                if rp[i][c + k] - rp[i][c] != target:
                    return False
            for j in range(c, c + k):
                if cp[j][r + k] - cp[j][r] != target:
                    return False
            d1 = 0
            d2 = 0
            for t in range(k):
                d1 += grid[r + t][c + t]
                d2 += grid[r + t][c + k - 1 - t]
            return d1 == target and d2 == target

        for k in range(min(m, n), 1, -1):
            for r in range(m - k + 1):
                for c in range(n - k + 1):
                    if check(r, c, k):
                        return k
        return 1
