from typing import List

class Solution:
    def maxCompatibilitySum(self, students: List[List[int]], mentors: List[List[int]]) -> int:
        m = len(students)
        n = len(students[0])
        score = [[sum(1 for k in range(n) if students[i][k] == mentors[j][k]) for j in range(m)] for i in range(m)]
        NEG = float('-inf')
        dp = [NEG] * (1 << m)
        dp[0] = 0
        for mask in range(1 << m):
            if dp[mask] == NEG:
                continue
            i = bin(mask).count('1')
            if i >= m:
                continue
            for j in range(m):
                if not (mask >> j) & 1:
                    nm = mask | (1 << j)
                    v = dp[mask] + score[i][j]
                    if v > dp[nm]:
                        dp[nm] = v
        return dp[(1 << m) - 1]
