Classic approach: use a sliding window over fruit positions. For a window covering positions [L, R] (both fruit positions), the cost is `min(|startPos - L|, |startPos - R|) + (R - L)` — go to the nearer end first, then traverse to the other. Expand the right end, shrink the left end while the cost exceeds k, track the max sum.

```python
from typing import List

class Solution:
    def maxTotalFruits(self, fruits: List[List[int]], startPos: int, k: int) -> int:
        def cost(l: int, r: int) -> int:
            L = fruits[l][0]
            R = fruits[r][0]
            return (R - L) + min(abs(startPos - L), abs(startPos - R))

        n = len(fruits)
        best = 0
        total = 0
        left = 0
        for right in range(n):
            total += fruits[right][1]
            while left <= right and cost(left, right) > k:
                total -= fruits[left][1]
                left += 1
            if left <= right:
                best = max(best, total)
        return best
```

