from typing import List

class Solution:
    def maxStudents(self, seats: List[List[str]]) -> int:
        m = len(seats)
        n = len(seats[0])
        # available mask per row
        avail = []
        for r in range(m):
            mask = 0
            for c in range(n):
                if seats[r][c].strip() == '.':
                    mask |= (1 << c)
            avail.append(mask)

        full = 1 << n
        # valid masks per row: subset of avail and no two adjacent bits
        valid_rows = []
        for r in range(m):
            vs = []
            for s in range(full):
                if (s & avail[r]) == s and (s & (s << 1)) == 0:
                    vs.append(s)
            valid_rows.append(vs)

        popcount = [bin(s).count('1') for s in range(full)]

        prev = {0: 0}
        for r in range(m):
            cur = {}
            for s in valid_rows[r]:
                best = -1
                for ps, val in prev.items():
                    # no upper-left / upper-right conflicts
                    if (s & (ps << 1)) == 0 and (s & (ps >> 1)) == 0:
                        if val > best:
                            best = val
                if best >= 0:
                    cur[s] = best + popcount[s]
            prev = cur

        return max(prev.values()) if prev else 0
```

