Standard approach: union-find on non-initial nodes; for each component, count which initial nodes touch it. Components touched by exactly one initial node are saved when that node is removed.

```python
from typing import List
from collections import defaultdict

class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        init_set = set(initial)
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        clean = [i for i in range(n) if i not in init_set]
        for i in clean:
            for j in clean:
                if i < j and graph[i][j]:
                    union(i, j)

        size = defaultdict(int)
        for i in clean:
            size[find(i)] += 1

        # For each component root, which initial nodes are adjacent
        comp_infectors = defaultdict(set)
        for u in initial:
            for v in clean:
                if graph[u][v]:
                    comp_infectors[find(v)].add(u)

        saved = defaultdict(int)
        for root, infectors in comp_infectors.items():
            if len(infectors) == 1:
                (u,) = tuple(infectors)
                saved[u] += size[root]

        best = -1
        best_saved = -1
        for u in sorted(initial):
            if saved[u] > best_saved:
                best_saved = saved[u]
                best = u
        return best
```

