Classic approach: group points by x-coordinate, sort each column's y-values, and for each pair of y-values in a column, record the last x seen for that pair. When the same pair appears again at a new x, a rectangle is formed.

```python
from typing import List
from collections import defaultdict

class Solution:
    def minAreaRect(self, points: List[List[int]]) -> int:
        columns = defaultdict(list)
        for x, y in points:
            columns[x].append(y)
        last_x = {}
        best = float('inf')
        for x in sorted(columns):
            ys = sorted(columns[x])
            n = len(ys)
            for i in range(n):
                for j in range(i + 1, n):
                    key = (ys[i], ys[j])
                    if key in last_x:
                        area = (x - last_x[key]) * (ys[j] - ys[i])
                        if area < best:
                            best = area
                    last_x[key] = x
        return 0 if best == float('inf') else best
```

