Classic approach: answer is 0 if already disconnected, 1 if removing some single land cell disconnects it, otherwise 2 (any grid can be disconnected by removing at most 2 cells, e.g., the two neighbors of a corner cell of the island).

```python
from typing import List

class Solution:
    def minDays(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def count_islands():
            seen = [[False] * n for _ in range(m)]
            cnt = 0
            for i in range(m):
                for j in range(n):
                    if grid[i][j] == 1 and not seen[i][j]:
                        cnt += 1
                        if cnt > 1:
                            return cnt
                        stack = [(i, j)]
                        seen[i][j] = True
                        while stack:
                            x, y = stack.pop()
                            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                                nx, ny = x + dx, y + dy
                                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 1 and not seen[nx][ny]:
                                    seen[nx][ny] = True
                                    stack.append((nx, ny))
            return cnt

        if count_islands() != 1:
            return 0

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    grid[i][j] = 0
                    c = count_islands()
                    grid[i][j] = 1
                    if c != 1:
                        return 1
        return 2
```

