Classic bitmask DP: for each subset, store (sessions, remaining time in current session), computing by adding one task at a time.

```python
from typing import List

class Solution:
    def minSessions(self, tasks: List[int], sessionTime: int) -> int:
        n = len(tasks)
        full = (1 << n) - 1
        INF = float('inf')
        # dp[mask] = (min sessions, min time used in last session)
        dp = [(INF, INF)] * (1 << n)
        dp[0] = (1, 0)
        for mask in range(1 << n):
            cur_sessions, cur_used = dp[mask]
            if cur_sessions == INF:
                continue
            for i in range(n):
                if mask & (1 << i):
                    continue
                nmask = mask | (1 << i)
                t = tasks[i]
                if cur_used + t <= sessionTime:
                    cand = (cur_sessions, cur_used + t)
                else:
                    cand = (cur_sessions + 1, t)
                if cand < dp[nmask]:
                    dp[nmask] = cand
        return dp[full][0]
```

