Classic backtracking: sort descending, fill buckets one at a time, prune duplicates and states via memoization on bitmask.

```python
from typing import List
from functools import lru_cache

class Solution:
    def canPartitionKSubsets(self, nums: List[int], k: int) -> bool:
        total = sum(nums)
        if total % k != 0:
            return False
        target = total // k
        nums.sort(reverse=True)
        if nums[0] > target:
            return False
        n = len(nums)
        full = (1 << n) - 1

        @lru_cache(maxsize=None)
        def dfs(mask: int, cur: int) -> bool:
            # cur is current bucket sum (mod target)
            if mask == full:
                return True
            for i in range(n):
                if mask & (1 << i):
                    continue
                # skip duplicates when previous identical element also unused
                if i > 0 and nums[i] == nums[i - 1] and not (mask & (1 << (i - 1))):
                    continue
                if cur + nums[i] <= target:
                    nxt = cur + nums[i]
                    if nxt == target:
                        nxt = 0
                    if dfs(mask | (1 << i), nxt):
                        return True
                    if cur == 0:
                        # first element in a fresh bucket failed -> no solution
                        return False
            return False

        return dfs(0, 0)
```

