from typing import List

class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        # Count minimum removals needed
        left_rem = 0
        right_rem = 0
        for ch in s:
            if ch == '(':
                left_rem += 1
            elif ch == ')':
                if left_rem > 0:
                    left_rem -= 1
                else:
                    right_rem += 1

        results = set()
        n = len(s)

        def dfs(idx: int, l_rem: int, r_rem: int, balance: int, path: list):
            if balance < 0 or l_rem < 0 or r_rem < 0:
                return
            if idx == n:
                if l_rem == 0 and r_rem == 0 and balance == 0:
                    results.add("".join(path))
                return
            ch = s[idx]
            if ch == '(':
                # Option: remove this '('
                if l_rem > 0:
                    dfs(idx + 1, l_rem - 1, r_rem, balance, path)
                # Option: keep it
                path.append(ch)
                dfs(idx + 1, l_rem, r_rem, balance + 1, path)
                path.pop()
            elif ch == ')':
                # Option: remove this ')'
                if r_rem > 0:
                    dfs(idx + 1, l_rem, r_rem - 1, balance, path)
                # Option: keep it
                if balance > 0:
                    path.append(ch)
                    dfs(idx + 1, l_rem, r_rem, balance - 1, path)
                    path.pop()
            else:
                path.append(ch)
                dfs(idx + 1, l_rem, r_rem, balance, path)
                path.pop()

        dfs(0, left_rem, right_rem, 0, [])
        return list(results)
```

