        result = result[::-1]
        nonzero = set(w[-1] for w in words if len(w) > 1)
        if len(result) > 1:
            nonzero.add(result[-1])
        assign = {}
        used = [False] * 10
        m = len(words)

        def solve(col, idx, carry):
